<summary>Original prompt</summary>

> Přidej příklad:
> 
> digraph {
>             start->ifa;
>             ifa->x;
>             ifa->A1;
>             x->ifc;
>             ifc->y;
>             ifc->z;
>             y->A2;
>             z->A1;
>             A1->d;
>             d->A2;
>             A2->start2;
>             
>             
>             start2->ifex;
>             ifex->end;
>             
>             ifex->ifa2;
>             ifa2->x2;
>             ifa2->A12;
>             x2->ifc2;
>             ifc2->y2;
>             ifc2->z2;
>             y2->A22;
>             z2->A12;
>             A12->d2;
>             d2->A22;
>             A22->start2;
> }
> 
> Ve výsledném Pseudokódu:
> ...
> while(true) {
>     start2;
>     start2_cont: {
>         if (ifex) {
>             break; //tohle je vnitřní break, měl by tak obsahovat label od loopu
>         }
>         if (ifa2) {
>             x2;
>             if (ifc2) {
>                 y2;
>                 break start2_cont;
>             }
>             z2;
>             A12;
>             d2;
>             break start2_cont;
>         } else {
>             A12;  //uzly A12, d2 by se neměly v kódu opakovat
>             d2;
>             break start2_cont;
>         }
>     }
>     A22;
> }


</details>



